// İki giriş de buradan geçer:
//  • Webhook ile gelen istekte alanlar "body" içindedir,
//  • Workflow 05'in /tarih ve /tarihler komutlarında alanlar doğrudan gelir.
// Sözdizimi Telegram ile aynı: {"metin": "ekle 14.03.1964 Annemin doğum günü"}
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body');
const govde = webhooktan ? (j.body && typeof j.body === 'object' ? j.body : {}) : j;

const chat_id = govde.chat_id ? String(govde.chat_id) : '';
const ISLEMLER = { liste: 'liste', ekle: 'ekle', sil: 'sil' };
const metin = String(govde.metin || '').trim();
const ilk = metin.split(/\s+/)[0].toLowerCase();
let islem = 'liste';
let arg = '';
if (metin) {
  islem = ISLEMLER[ilk] || 'bilinmeyen';
  arg = ISLEMLER[ilk] ? metin.slice(ilk.length).trim() : metin;
}

return [{ json: { islem, arg, chat_id, webhooktan } }];

// ── Ortak: yıllık tekrar eden tarihin sıradaki günü ─────────────────────────
// "1964-03-14" yıllı, "--03-14" yılsız tarih. 29 Şubat, artık olmayan
// yıllarda 28 Şubat'ta sayılır. Tarihler yerel saatle (GENERIC_TIMEZONE).
const iki = (n) => String(n).padStart(2, '0');
const anahtar = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1) + '-' + iki(d.getDate());
const bugun = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; })();
const EMOJI = { dogumgunu: '🎂', yildonumu: '💍', diger: '📅' };

const tarihCoz = (t) => {
  const m = String(t || '').match(/^(\d{4}|-)-(\d{2})-(\d{2})$/);
  if (!m) return null;
  const yil = m[1] === '-' ? null : Number(m[1]);
  const ay = Number(m[2]);
  const gun = Number(m[3]);
  if (ay < 1 || ay > 12 || gun < 1 || gun > 31) return null;
  return { yil, ay, gun };
};
const tarihiDuzenle = (t) => ({
  ...t,
  id: Number(t.id) || 0,
  ad: String(t.ad || '').trim(),
  tur: EMOJI[t.tur] ? t.tur : 'diger',
  onceden: (Array.isArray(t.onceden) ? t.onceden : [7, 1]).map(Number).filter((n) => Number.isInteger(n) && n > 0),
  sonBildirim: t.sonBildirim || null,
});
const siradaki = (t) => {
  const c = tarihCoz(t.tarih);
  if (!c) return null;
  const yilIcin = (y) => new Date(y, c.ay - 1, Math.min(c.gun, new Date(y, c.ay, 0).getDate()));
  let d = yilIcin(bugun.getFullYear());
  if (d < bugun) d = yilIcin(bugun.getFullYear() + 1);
  const n = Math.round((d.getTime() - bugun.getTime()) / 86400000);
  const kacinci = c.yil ? d.getFullYear() - c.yil : null;
  return { d, n, kacinci };
};
const neZaman = (n) => (n === 0 ? 'Bugün' : n === 1 ? 'Yarın' : n + ' gün sonra');
const tarihMetni = (d) => d.toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });
const kacinciMetni = (t, k) => {
  if (!k || k < 1) return '';
  return t.tur === 'dogumgunu' ? k + ' yaşına giriyor' : k + '. yıl';
};
// ─────────────────────────────────────────────────────────────────────────────
// Liste / ekle / sil. Dosya bozuksa durur — aksi hâlde liste boş sanılıp
// üzerine yazılır ve tüm tarihler kaybolur.
const okuHata = $('Tarihleri Oku').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Tarihleri Çıkar').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('tarihler.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}

const istek = $('İsteği Al (Tarih)').first().json;
const okunan = dosyaYok ? {} : ($input.first().json || {});
const veri = okunan.data || okunan;
const tarihler = (Array.isArray(veri.tarihler) ? veri.tarihler : [])
  .filter((t) => t && t.ad)
  .map(tarihiDuzenle);

const turBul = (ad) => {
  const k = String(ad).toLocaleLowerCase('tr-TR');
  if (/doğum|dogum/.test(k)) return 'dogumgunu';
  if (/y[ıi]l\s*d[öo]n[üu]m|evlilik|nişan|nisan/.test(k)) return 'yildonumu';
  return 'diger';
};

const liste = () => {
  const sirali = tarihler
    .map((t) => ({ t, s: siradaki(t) }))
    .filter((x) => x.s)
    .sort((a, b) => a.s.n - b.s.n);
  if (sirali.length === 0) return 'Kayıtlı tarih yok.\nEklemek için: /tarih ekle 14.03.1964 Annemin doğum günü';
  const ilk = sirali.slice(0, 10);
  return '📅 Yaklaşan tarihler\n' + ilk.map(({ t, s }) => {
    const k = kacinciMetni(t, s.kacinci);
    return EMOJI[t.tur] + ' #' + t.id + ' ' + t.ad + ' — ' + tarihMetni(s.d) + ' (' +
      (s.n === 0 ? 'bugün' : s.n + ' gün') + (k ? ', ' + k : '') + ')';
  }).join('\n') + (sirali.length > ilk.length ? '\n… ve ' + (sirali.length - ilk.length) + ' tane daha' : '');
};

let mesaj = '';
let yazilsin = false;
let hata = false;

if (istek.islem === 'liste') {
  mesaj = liste();
} else if (istek.islem === 'ekle') {
  // "14.03.1964 Annemin doğum günü" · "02.06 Evlilik yıl dönümü" · "14/03 ..."
  const m = istek.arg.match(/^(\d{1,2})[./](\d{1,2})(?:[./](\d{4}))?\s+(.+)$/);
  const gun = m ? Number(m[1]) : 0;
  const ay = m ? Number(m[2]) : 0;
  const yil = m && m[3] ? Number(m[3]) : null;
  const gecerli = m && ay >= 1 && ay <= 12 && gun >= 1 &&
    gun <= new Date(yil || 2000, ay, 0).getDate() && (!yil || yil <= bugun.getFullYear());
  if (!gecerli) {
    hata = true;
    mesaj = [
      'Kullanım:',
      '• /tarih ekle 14.03.1964 Annemin doğum günü → yıl varsa yaşını da söylerim',
      '• /tarih ekle 02.06 Evlilik yıl dönümü',
    ].join('\n');
  } else {
    const ad = m[4].trim().slice(0, 80);
    const id = tarihler.reduce((mx, t) => Math.max(mx, t.id), 0) + 1;
    const tarih = (yil ? String(yil) : '-') + '-' + iki(ay) + '-' + iki(gun);
    const yeni = tarihiDuzenle({ id, ad, tarih, tur: turBul(ad), onceden: [7, 1], olusturulma: new Date().toISOString() });
    tarihler.push(yeni);
    yazilsin = true;
    const s = siradaki(yeni);
    const k = kacinciMetni(yeni, s.kacinci);
    mesaj = '➕ ' + EMOJI[yeni.tur] + ' Eklendi: #' + id + ' ' + ad + '\nSıradaki: ' + tarihMetni(s.d) +
      ' (' + (s.n === 0 ? 'bugün' : s.n + ' gün sonra') + (k ? ', ' + k : '') + ')' +
      '\n7 gün ve 1 gün önce, bir de gününde hatırlatırım.';
  }
} else if (istek.islem === 'sil') {
  const id = Number((istek.arg.match(/#?(\d+)/) || [])[1]) || 0;
  const t = tarihler.find((x) => x.id === id);
  if (!t) {
    hata = true;
    mesaj = (id ? '#' + id + ' bulunamadı.' : 'Kullanım: /tarih sil 3') + '\n\n' + liste();
  } else {
    tarihler.splice(tarihler.indexOf(t), 1);
    yazilsin = true;
    mesaj = '🗑 Silindi: #' + t.id + ' ' + t.ad;
  }
} else {
  hata = true;
  mesaj = [
    'Önemli tarih komutları:',
    '• /tarihler → yaklaşan 10 tarih',
    '• /tarih ekle 14.03.1964 Annemin doğum günü',
    '• /tarih ekle 02.06 Evlilik yıl dönümü',
    '• /tarih sil 3',
  ].join('\n');
}

const sonuc = tarihler.map((t) => {
  const s = siradaki(t);
  return { id: t.id, ad: t.ad, tarih: t.tarih, tur: t.tur,
           siradaki: s ? anahtar(s.d) : null, kalanGun: s ? s.n : null, kacinci: s ? s.kacinci : null };
});

return [{
  json: {
    islem: istek.islem, chat_id: istek.chat_id, webhooktan: istek.webhooktan,
    mesaj, hata, sonuc, yazilsin, tarihler,
  },
}];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// İstek Telegram'dan geldiyse sonuç oraya gider.
const j = $input.first().json;
if (!j.chat_id) return [];
return [{ json: { chat_id: j.chat_id, text: String(j.mesaj).slice(0, 3900) } }];

// Dosyaya yalnızca tarih listesi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { tarihler: j.tarihler } }];

// ── Ortak: yıllık tekrar eden tarihin sıradaki günü ─────────────────────────
// "1964-03-14" yıllı, "--03-14" yılsız tarih. 29 Şubat, artık olmayan
// yıllarda 28 Şubat'ta sayılır. Tarihler yerel saatle (GENERIC_TIMEZONE).
const iki = (n) => String(n).padStart(2, '0');
const anahtar = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1) + '-' + iki(d.getDate());
const bugun = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; })();
const EMOJI = { dogumgunu: '🎂', yildonumu: '💍', diger: '📅' };

const tarihCoz = (t) => {
  const m = String(t || '').match(/^(\d{4}|-)-(\d{2})-(\d{2})$/);
  if (!m) return null;
  const yil = m[1] === '-' ? null : Number(m[1]);
  const ay = Number(m[2]);
  const gun = Number(m[3]);
  if (ay < 1 || ay > 12 || gun < 1 || gun > 31) return null;
  return { yil, ay, gun };
};
const tarihiDuzenle = (t) => ({
  ...t,
  id: Number(t.id) || 0,
  ad: String(t.ad || '').trim(),
  tur: EMOJI[t.tur] ? t.tur : 'diger',
  onceden: (Array.isArray(t.onceden) ? t.onceden : [7, 1]).map(Number).filter((n) => Number.isInteger(n) && n > 0),
  sonBildirim: t.sonBildirim || null,
});
const siradaki = (t) => {
  const c = tarihCoz(t.tarih);
  if (!c) return null;
  const yilIcin = (y) => new Date(y, c.ay - 1, Math.min(c.gun, new Date(y, c.ay, 0).getDate()));
  let d = yilIcin(bugun.getFullYear());
  if (d < bugun) d = yilIcin(bugun.getFullYear() + 1);
  const n = Math.round((d.getTime() - bugun.getTime()) / 86400000);
  const kacinci = c.yil ? d.getFullYear() - c.yil : null;
  return { d, n, kacinci };
};
const neZaman = (n) => (n === 0 ? 'Bugün' : n === 1 ? 'Yarın' : n + ' gün sonra');
const tarihMetni = (d) => d.toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });
const kacinciMetni = (t, k) => {
  if (!k || k < 1) return '';
  return t.tur === 'dogumgunu' ? k + ' yaşına giriyor' : k + '. yıl';
};
// ─────────────────────────────────────────────────────────────────────────────
// Sabah kontrolü: gününde ve "onceden" listesindeki günlerde (varsayılan 7 ve 1
// gün kala) bildirir. Aynı gün ikinci kez yazmaz (sonBildirim) — "Elle Test
// Et" ile çalıştırıldığında hariç.
const okuHata = $('Tarihleri Oku (Sabah)').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Tarihleri Çıkar (Sabah)').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('tarihler.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}
if (dosyaYok) return [{ json: { gonderilecek: false, yazilsin: false } }];

let elle = false;
try { elle = $('Elle Test Et (Tarih)').all().length > 0; } catch (e) { elle = false; }

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const okunan = $input.first().json || {};
const veri = okunan.data || okunan;
const tarihler = (Array.isArray(veri.tarihler) ? veri.tarihler : [])
  .filter((t) => t && t.ad)
  .map(tarihiDuzenle);

const bildirilecek = [];
for (const t of tarihler) {
  const s = siradaki(t);
  if (!s || (s.n !== 0 && !t.onceden.includes(s.n))) continue;
  const isaret = anahtar(s.d) + '|' + s.n;
  if (!elle && t.sonBildirim === isaret) continue;
  t.sonBildirim = isaret;
  bildirilecek.push({ t, s });
}
if (bildirilecek.length === 0) return [{ json: { gonderilecek: false, yazilsin: false } }];

bildirilecek.sort((a, b) => a.s.n - b.s.n);
const satirlar = bildirilecek.map(({ t, s }) => {
  const k = kacinciMetni(t, s.kacinci);
  return EMOJI[t.tur] + ' ' + neZaman(s.n) + (s.n > 1 ? ' (' + tarihMetni(s.d) + ')' : '') + ': ' +
    t.ad + (k ? ' — ' + k : '') + (s.n === 0 ? '!' : '');
});
const text = satirlar.join('\n');

return [{
  json: {
    gonderilecek: true,
    yazilsin: true,
    text,
    konu: satirlar[0] + (satirlar.length > 1 ? ' (+' + (satirlar.length - 1) + ')' : ''),
    html: '<ul>' + satirlar.map((s) => '<li>' + esc(s) + '</li>').join('') + '</ul>',
    govde: { tarihler },
  },
}];

// Telegram kuruluysa hatırlatma oraya gider; değilse bu dal boş döner.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE hatırlatma mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];

// Bildirilen tarihler işaretlenir: aynı gün ikinci kez yazılmaz.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: j.govde }];
